CREATE TABLE public.bank_import_guard_settings(singleton boolean PRIMARY KEY DEFAULT true CHECK(singleton),enforced boolean NOT NULL DEFAULT false);
GRANT SELECT ON public.bank_import_guard_settings TO authenticated;
GRANT ALL ON public.bank_import_guard_settings TO service_role;
ALTER TABLE public.bank_import_guard_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY bank_guard_settings_read ON public.bank_import_guard_settings FOR SELECT TO authenticated USING(public.is_admin());
CREATE OR REPLACE FUNCTION public.bank_import_guard_enforced() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce((SELECT enforced FROM public.bank_import_guard_settings WHERE singleton),false) $$;
REVOKE ALL ON FUNCTION public.bank_import_guard_enforced() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.bank_import_guard_enforced() TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.set_bank_import_guard_enforced(_enabled boolean) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR NOT public.is_super_admin() THEN RAISE EXCEPTION 'Somente super admin pode ativar a proteção após publicação.'; END IF; IF _enabled IS NULL THEN RAISE EXCEPTION 'Informe o estado.'; END IF; INSERT INTO public.bank_import_guard_settings(singleton,enforced) VALUES(true,_enabled) ON CONFLICT(singleton) DO UPDATE SET enforced=excluded.enforced; RETURN _enabled; END $$;
REVOKE ALL ON FUNCTION public.set_bank_import_guard_enforced(boolean) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.set_bank_import_guard_enforced(boolean) TO authenticated;
CREATE OR REPLACE FUNCTION public.bank_registered_code(_bank text,_code text DEFAULT NULL) RETURNS text LANGUAGE plpgsql IMMUTABLE SET search_path=public AS $$ DECLARE k text; c text; b text:=lower(regexp_replace(trim(coalesce(_bank,'')),'\s+',' ','g')); BEGIN b:=translate(b,'áàâãéêíóôõúç','aaaaeeiooouc'); k:=CASE b WHEN 'bradesco' THEN '237' WHEN 'banco bradesco' THEN '237' WHEN 'sicredi' THEN '748' WHEN 'banco sicredi' THEN '748' WHEN 'sicoob' THEN '756' WHEN 'banco sicoob' THEN '756' WHEN 'banco do brasil' THEN '001' WHEN 'bb' THEN '001' WHEN 'itau' THEN '341' WHEN 'banco itau' THEN '341' WHEN 'itau unibanco' THEN '341' WHEN 'inter' THEN '077' WHEN 'banco inter' THEN '077' WHEN 'caixa' THEN '104' WHEN 'cef' THEN '104' WHEN 'caixa economica federal' THEN '104' WHEN 'santander' THEN '033' WHEN 'banco santander' THEN '033' WHEN 'nubank' THEN '260' WHEN 'nu' THEN '260' WHEN 'c6 bank' THEN '336' WHEN 'c6' THEN '336' WHEN 'banco c6' THEN '336' WHEN 'safra' THEN '422' WHEN 'banco safra' THEN '422' WHEN 'banrisul' THEN '041' WHEN 'sisprime' THEN '084' WHEN 'sisprime do brasil' THEN '084' WHEN 'stone' THEN '197' WHEN 'pagbank' THEN '290' WHEN 'pagseguro' THEN '290' WHEN 'mercado pago' THEN '323' WHEN 'picpay' THEN '380' ELSE CASE WHEN b ~ '^[0-9]{1,3}$' THEN lpad(b,3,'0') ELSE '' END END; c:=CASE WHEN trim(coalesce(_code,'')) ~ '^[0-9]{1,3}$' THEN lpad(trim(_code),3,'0') ELSE '' END; IF coalesce(_code,'')<>'' AND c='' THEN RETURN ''; END IF; IF c<>'' AND k<>'' AND c<>k THEN RETURN ''; END IF; RETURN coalesce(nullif(c,''),k,''); END $$;
ALTER TABLE public.bank_accounts ADD COLUMN holder_entity_id uuid REFERENCES public.company_entities(id);
CREATE OR REPLACE FUNCTION public.guard_bank_account_identity() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE code text; BEGIN
PERFORM pg_advisory_xact_lock(7711442201);
code:=public.bank_registered_code(NEW.banco,NEW.bank_code);
IF NEW.holder_entity_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.company_entities e WHERE e.id=NEW.holder_entity_id AND e.school_id=NEW.school_id AND (coalesce(NEW.holder_document,'')='' OR public.bank_identity_norm(e.cnpj)=public.bank_identity_norm(NEW.holder_document))) THEN RAISE EXCEPTION 'Titular específico não pertence à empresa ou documento diverge.'; END IF;
IF coalesce(NEW.holder_document,'')<>'' AND public.bank_identity_norm(NEW.holder_document) !~ '^([0-9]{11}|[0-9]{14})$' THEN RAISE EXCEPTION 'Documento do titular inválido.'; END IF;
IF TG_OP='INSERT' OR NEW.banco IS DISTINCT FROM OLD.banco OR NEW.bank_code IS DISTINCT FROM OLD.bank_code OR NEW.agencia IS DISTINCT FROM OLD.agencia OR NEW.conta IS DISTINCT FROM OLD.conta OR NEW.school_id IS DISTINCT FROM OLD.school_id THEN
 IF code<>'' AND public.bank_identity_norm(NEW.agencia)<>'' AND public.bank_identity_norm(NEW.conta)<>'' AND EXISTS(SELECT 1 FROM public.bank_accounts a WHERE a.id<>NEW.id AND NOT a.is_virtual AND public.bank_registered_code(a.banco,a.bank_code)=code AND public.bank_identity_norm(a.agencia)=public.bank_identity_norm(NEW.agencia) AND public.bank_identity_norm(a.conta)=public.bank_identity_norm(NEW.conta)) THEN RAISE EXCEPTION 'Cadastro bancário duplicado ou ambíguo. Corrija o vínculo da conta.'; END IF;
END IF; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.guard_bank_import_destination() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE a public.bank_accounts; BEGIN SELECT * INTO a FROM public.bank_accounts WHERE id=NEW.account_id;
IF a.id IS NULL OR a.school_id<>NEW.school_id THEN RAISE EXCEPTION 'Conta não vinculada à empresa.'; END IF;
IF TG_OP='UPDATE' AND (NEW.school_id IS DISTINCT FROM OLD.school_id OR NEW.account_id IS DISTINCT FROM OLD.account_id OR NEW.identity_checked IS DISTINCT FROM OLD.identity_checked) THEN RAISE EXCEPTION 'Destino e validação do extrato são imutáveis.'; END IF;
IF TG_OP='INSERT' AND coalesce(auth.role(),'')<>'service_role' AND (NEW.identity_checked OR (public.bank_import_guard_enforced() AND (NEW.file_path IS NOT NULL OR NEW.total_linhas>0 OR NEW.formato='api_inter' OR NEW.file_hash NOT LIKE 'manual-%' OR NOT public.is_super_admin()))) THEN RAISE EXCEPTION 'Extratos devem ser validados pelo servidor antes de gravar.'; END IF;
RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.guard_bank_tx_destination() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN
IF NOT EXISTS(SELECT 1 FROM public.bank_accounts a WHERE a.id=NEW.account_id AND a.school_id=NEW.school_id) THEN RAISE EXCEPTION 'Destino bancário inválido.'; END IF;
IF NEW.manual_pair_id IS NOT NULL THEN IF NOT EXISTS(SELECT 1 FROM public.bank_accounts a WHERE a.id=NEW.account_id AND a.is_virtual) THEN RAISE EXCEPTION 'Conta virtual necessária.'; END IF;
ELSE IF NOT EXISTS(SELECT 1 FROM public.bank_statement_imports i WHERE i.id=NEW.import_id AND i.account_id=NEW.account_id AND i.school_id=NEW.school_id) THEN RAISE EXCEPTION 'Lançamento não pertence ao destino do extrato.'; END IF;
IF TG_OP='INSERT' AND public.bank_import_guard_enforced() AND coalesce(auth.role(),'')<>'service_role' THEN RAISE EXCEPTION 'Importação de movimentos exige validação no servidor.'; END IF; END IF; RETURN NEW; END $$;
DROP POLICY bank_statement_server_upload_only ON storage.objects;
CREATE POLICY bank_statement_server_upload_only ON storage.objects AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK(bucket_id<>'bank-statements' OR NOT public.bank_import_guard_enforced());
CREATE OR REPLACE FUNCTION public.commit_verified_bank_import(_user uuid,_school uuid,_account uuid,_identity jsonb,_meta jsonb,_rows jsonb,_links jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a public.bank_accounts; iid uuid; r jsonb; code text; doc text; BEGIN
IF coalesce(auth.role(),'')<>'service_role' THEN RAISE EXCEPTION 'Acesso não autorizado.'; END IF;
IF NOT (public.has_role(_user,'admin') OR public.has_role(_user,'super_admin')) OR (EXISTS(SELECT 1 FROM public.schools WHERE id=_school AND restrita) AND NOT public.has_role(_user,'super_admin')) THEN RAISE EXCEPTION 'Sem autorização para esta empresa.'; END IF;
PERFORM pg_advisory_xact_lock(7711442201);
SELECT * INTO a FROM public.bank_accounts WHERE id=_account AND school_id=_school FOR UPDATE;
IF a.id IS NULL OR NOT a.ativa OR a.is_virtual THEN RAISE EXCEPTION 'Conta não vinculada à empresa.'; END IF;
code:=public.bank_registered_code(a.banco,a.bank_code);
IF code='' OR public.bank_identity_norm(a.agencia)='' OR public.bank_identity_norm(a.conta)='' THEN RAISE EXCEPTION 'Complete o cadastro da conta.'; END IF;
IF coalesce((_identity->>'ambiguous')::boolean,false) OR coalesce(_identity->>'bankCode','') !~ '^[0-9]{1,3}$' OR lpad(_identity->>'bankCode',3,'0')<>code OR public.bank_identity_norm(_identity->>'branch')='' OR public.bank_identity_norm(_identity->>'branch')<>public.bank_identity_norm(a.agencia) OR public.bank_identity_norm(_identity->>'account')='' OR public.bank_identity_norm(_identity->>'account')<>public.bank_identity_norm(a.conta) THEN RAISE EXCEPTION 'Identidade do extrato diverge do destino.'; END IF;
doc:=public.bank_identity_norm(a.holder_document);
IF a.holder_entity_id IS NOT NULL THEN
 SELECT public.bank_identity_norm(e.cnpj) INTO doc FROM public.company_entities e WHERE e.id=a.holder_entity_id AND e.school_id=a.school_id AND (coalesce(a.holder_document,'')='' OR public.bank_identity_norm(e.cnpj)=public.bank_identity_norm(a.holder_document));
 IF doc IS NULL THEN RAISE EXCEPTION 'Vínculo do titular específico inválido.'; END IF;
END IF;
IF _identity ? 'holderDocument' AND (public.bank_identity_norm(_identity->>'holderDocument') !~ '^([0-9]{11}|[0-9]{14})$' OR public.bank_identity_norm(_identity->>'holderDocument')<>coalesce(doc,'')) THEN RAISE EXCEPTION 'Titular diverge do cadastro autorizado.'; END IF;
IF EXISTS(SELECT 1 FROM public.bank_accounts b WHERE b.id<>a.id AND NOT b.is_virtual AND public.bank_registered_code(b.banco,b.bank_code)=code AND public.bank_identity_norm(b.agencia)=public.bank_identity_norm(a.agencia) AND public.bank_identity_norm(b.conta)=public.bank_identity_norm(a.conta)) THEN RAISE EXCEPTION 'Vínculo bancário ambíguo.'; END IF;
IF jsonb_typeof(_rows)<>'array' OR jsonb_array_length(_rows)>20000 OR _meta->>'formato' NOT IN('ofx','csv','xlsx') OR _meta->>'file_hash' !~ '^[a-f0-9]{64}$' OR _meta->>'file_path' NOT LIKE _school::text||'/'||_account::text||'/%' THEN RAISE EXCEPTION 'Lote inválido.'; END IF;
SELECT id INTO iid FROM public.bank_statement_imports WHERE account_id=_account AND file_hash=_meta->>'file_hash'; IF iid IS NOT NULL THEN RAISE EXCEPTION 'Arquivo já importado.'; END IF;
INSERT INTO public.bank_statement_imports(school_id,account_id,file_name,file_path,file_hash,formato,periodo_inicio,periodo_fim,total_linhas,inseridas,duplicadas,total_entradas,total_saidas,imported_by,saldo_final_informado,saldo_aplicado_informado,saldo_retido_informado,identity_checked) VALUES(_school,_account,_meta->>'file_name',_meta->>'file_path',_meta->>'file_hash',_meta->>'formato',_meta->>'periodo_inicio',_meta->>'periodo_fim',(_meta->>'total_linhas')::int,jsonb_array_length(_rows),(_meta->>'duplicadas')::int,(_meta->>'total_entradas')::numeric,(_meta->>'total_saidas')::numeric,_user,(_meta->>'saldo_final_informado')::numeric,(_meta->>'saldo_aplicado_informado')::numeric,(_meta->>'saldo_retido_informado')::numeric,true) RETURNING id INTO iid;
FOR r IN SELECT value FROM jsonb_array_elements(_rows) LOOP INSERT INTO public.bank_transactions(school_id,account_id,import_id,data,descricao,valor,tipo,bank_ref,dedup_hash,movement_kind,is_forecast) VALUES(_school,_account,iid,r->>'data',r->>'descricao',(r->>'valor')::numeric,r->>'tipo',r->>'bank_ref',r->>'dedup_hash',r->>'movement_kind',coalesce((r->>'is_forecast')::boolean,false)) ON CONFLICT(account_id,dedup_hash) DO NOTHING; END LOOP;
FOR r IN SELECT value FROM jsonb_array_elements(_links) LOOP UPDATE public.bank_transactions SET bank_ref=r->>'bankRef' WHERE id=(r->>'id')::uuid AND account_id=_account AND school_id=_school AND (bank_ref IS NULL OR coalesce((r->>'replace')::boolean,false)); END LOOP; RETURN iid; END $$;
COMMENT ON COLUMN public.bank_accounts.identity_verified IS 'DEPRECATED: completeness and unambiguous registered identity replace manual confirmation; historical values retained.';
COMMENT ON TABLE public.bank_import_guard_settings IS 'Transition defaults to legacy uploads permitted by existing RLS; owner enables full server-only enforcement after frontend publication.';